-- ============================================================================
-- LOOK Restobar -- seed data v2, rebuilt directly from the venue's official
-- "Meniu Sala" PDF (Aug 2026 edition) -- names, prices, weights and dish
-- photography all verified against that source. Run once, after schema.sql,
-- on a FRESH (empty) database.
--
-- Idempotent by design: each block only inserts when its table is still
-- empty, so running this again after the admin has edited, added or deleted
-- anything never overwrites or duplicates their work.
--
-- Already have live data that needs to match this update? Don't run this
-- file -- run supabase/menu_refresh_2026.sql instead, which replaces
-- everything in place (see docs/ADMIN.md).
-- ============================================================================

insert into public.menu_categories (slug, name, icon, sort_order, translations, emoji)
select * from (values
  ('gustari', 'Gustări', 'bread', 0, '{"ru":{"name":"Закуски"},"en":{"name":"Starters"}}'::jsonb, "🥗"),
  ('salate', 'Salate', 'leaf', 10, '{"ru":{"name":"Салаты"},"en":{"name":"Salads"}}'::jsonb, "🥬"),
  ('supe', 'Supe', 'bowl', 20, '{"ru":{"name":"Супы"},"en":{"name":"Soups"}}'::jsonb, "🍲"),
  ('paste', 'Paste', 'noodle', 30, '{"ru":{"name":"Паста"},"en":{"name":"Pasta"}}'::jsonb, "🍝"),
  ('peste', 'Pește & Fructe de mare', 'fish', 40, '{"ru":{"name":"Рыба и морепродукты"},"en":{"name":"Fish & Seafood"}}'::jsonb, "🐟"),
  ('carne', 'Carne & Grătar', 'meat', 50, '{"ru":{"name":"Мясо и гриль"},"en":{"name":"Meat & Grill"}}'::jsonb, "🥩"),
  ('burgeri', 'Burgeri', 'burger', 60, '{"ru":{"name":"Бургеры"},"en":{"name":"Burgers"}}'::jsonb, "🍔"),
  ('platouri', 'Platouri pentru masă', 'platter', 70, '{"ru":{"name":"Блюда на компанию"},"en":{"name":"Sharing Platters"}}'::jsonb, "🍽️"),
  ('garnituri', 'Garnituri', 'fries', 80, '{"ru":{"name":"Гарниры"},"en":{"name":"Sides"}}'::jsonb, "🍟"),
  ('deserturi', 'Deserturi', 'cake', 90, '{"ru":{"name":"Десерты"},"en":{"name":"Desserts"}}'::jsonb, "🍰")
) as seed(slug, name, icon, sort_order, translations, emoji)
where not exists (select 1 from public.menu_categories);

insert into public.menu_items (category_id, name, description, price, weight, photo_url, signature, sort_order, translations)
select mc.id, seed.name, seed.description, seed.price, seed.weight, seed.photo_url, seed.signature, seed.sort_order, seed.translations
from (values
  ('gustari', 'Vitello Tonnato', 'Mușchiuleț de vită, mix de salată, sparanghel, capere, roșii cherry coapte, sos tonnato, ulei de trufe.', 200, '280 g', '/dish-photos/vittello-tonnato.jpg', false, 0, '{"ru": {"name": "Вителло Тоннато", "description": "Вырезка говядины, микс салата, спаржа, каперсы, запечённые томаты черри, соус тоннато, трюфельное масло."}, "en": {"name": "Vitello Tonnato", "description": "Beef tenderloin, salad mix, asparagus, capers, roasted cherry tomatoes, tonnato sauce, truffle oil."}}'::jsonb),
  ('gustari', 'Vânătă cu sos Parmigiano', 'Vânătă, roșii cherry coapte, sos parmigiano.', 135, '300 g', '/dish-photos/vanata-parmigiano.jpg', false, 10, '{"ru": {"name": "Баклажан с соусом пармиджано", "description": "Баклажан, запечённые томаты черри, соус пармиджано."}, "en": {"name": "Eggplant with Parmigiano Sauce", "description": "Eggplant, roasted cherry tomatoes, Parmigiano sauce."}}'::jsonb),
  ('gustari', 'Ardei copt cu sos tonnato', 'Ardei copt, sos tonnato, ciabatta.', 105, '300 g', '/dish-photos/ardei-copt-tonnato.jpg', false, 20, '{"ru": {"name": "Печёный перец с соусом тоннато", "description": "Печёный перец, соус тоннато, чиабатта."}, "en": {"name": "Roasted Pepper with Tonnato Sauce", "description": "Roasted pepper, tonnato sauce, ciabatta."}}'::jsonb),
  ('gustari', 'Tartar de ton', 'Ton, avocado, castraveți, caviar roșu, fulgi de ton, ceapă crocantă, sos de susan, chuka.', 200, '250 g', '/dish-photos/tartar-ton.jpg', true, 30, '{"ru": {"name": "Тартар из тунца", "description": "Тунец, авокадо, огурцы, красная икра, хлопья тунца, хрустящий лук, кунжутный соус, чука."}, "en": {"name": "Tuna Tartare", "description": "Tuna, avocado, cucumber, red caviar, tuna flakes, crispy onion, sesame sauce, chuka salad."}}'::jsonb),
  ('gustari', 'Tartar de somon', 'Somon, avocado, castraveți, caviar roșu, perle din orez, chips din crab, sos de susan.', 190, '250 g', '/dish-photos/tartar-somon.jpg', false, 40, '{"ru": {"name": "Тартар из лосося", "description": "Лосось, авокадо, огурцы, красная икра, рисовые жемчужины, крабовые чипсы, кунжутный соус."}, "en": {"name": "Salmon Tartare", "description": "Salmon, avocado, cucumber, red caviar, rice pearls, crab chips, sesame sauce."}}'::jsonb),
  ('gustari', 'Bruschetta cu somon', 'Ciabatta, cremă de cașcaval, somon s/s, ulei verde, castraveți, semințe de susan.', 120, '150 g', '/dish-photos/bruschetta-somon.jpg', false, 50, '{"ru": {"name": "Брускетта с лососем", "description": "Чиабатта, сырный крем, слабосолёный лосось, зелёное масло, огурцы, кунжут."}, "en": {"name": "Salmon Bruschetta", "description": "Ciabatta, cheese cream, cured salmon, herb oil, cucumber, sesame seeds."}}'::jsonb),
  ('gustari', 'Bruschetta cu roast beef', 'Ciabatta, sos tonnato, roast beef, capere, cremă balsamică, cașcaval Parmigiano, semințe de susan.', 100, '150 g', '/dish-photos/bruschetta-roastbeef.jpg', false, 60, '{"ru": {"name": "Брускетта с ростбифом", "description": "Чиабатта, соус тоннато, ростбиф, каперсы, бальзамический крем, пармиджано, кунжут."}, "en": {"name": "Roast Beef Bruschetta", "description": "Ciabatta, tonnato sauce, roast beef, capers, balsamic cream, Parmigiano, sesame seeds."}}'::jsonb),
  ('gustari', 'Bruschetta cu roșii cherry', 'Ciabatta, sos bulgăresc, roșii cherry coapte, sos pesto, spanac, ulei verde.', 85, '150 g', '/dish-photos/bruschetta-rosii-chery.jpg', false, 70, '{"ru": {"name": "Брускетта с томатами черри", "description": "Чиабатта, болгарский соус, запечённые томаты черри, соус песто, шпинат, зелёное масло."}, "en": {"name": "Cherry Tomato Bruschetta", "description": "Ciabatta, Bulgarian-style sauce, roasted cherry tomatoes, pesto, spinach, herb oil."}}'::jsonb),
  ('gustari', 'Asorti de bruschete', 'Bruschetă cu somon, bruschetă cu roast beef, bruschetă cu roșii cherry.', 260, '450 g', '/dish-photos/asorti-bruschete.jpg', false, 80, '{"ru": {"name": "Ассорти брускетт", "description": "Брускетта с лососем, брускетта с ростбифом, брускетта с томатами черри."}, "en": {"name": "Bruschetta Assortment", "description": "Salmon bruschetta, roast beef bruschetta, cherry tomato bruschetta."}}'::jsonb),
  ('gustari', 'Midii pane', 'Carne de midii, tempura, sos de soia, usturoi, sos spicy, lămâie.', 180, '250 g', '/dish-photos/midii-pane.jpg', false, 90, '{"ru": {"name": "Мидии в панировке", "description": "Мясо мидий, темпура, соевый соус, чеснок, острый соус, лимон."}, "en": {"name": "Breaded Mussels", "description": "Mussel meat, tempura batter, soy sauce, garlic, spicy sauce, lemon."}}'::jsonb),
