  ('gustari', 'Calmar pane', 'Calmar, panco, ou, sos spicy, lămâie.', 180, '250 g', '/dish-photos/calmar-pane.jpg', false, 110, '{"ru": {"name": "Кальмар в панировке", "description": "Кальмар, панко, яйцо, острый соус, лимон."}, "en": {"name": "Breaded Calamari", "description": "Calamari, panko, egg, spicy sauce, lemon."}}'::jsonb),
