  ('gustari', 'Antipasti crudo', 'Salamuri italiene, olive, măsline, gressini.', 270, '380 g', '/dish-photos/antipasti-crudo.jpg', false, 130, '{"ru": {"name": "Антипасти крудо", "description": "Итальянские колбасы, оливки, маслины, гриссини."}, "en": {"name": "Antipasti Crudo", "description": "Italian cured meats, green and black olives, grissini."}}'::jsonb),
  ('salate', 'Salata cu creveți și mango', 'Mix de salată, creveți, mango, avocado, dressing de portocală.', 170, '280 g', '/dish-photos/salata-creveti-mango.jpg', false, 0, '{"ru": {"name": "Салат с креветками и манго", "description": "Микс салата, креветки, манго, авокадо, апельсиновая заправка."}, "en": {"name": "Shrimp & Mango Salad", "description": "Salad mix, shrimp, mango, avocado, orange dressing."}}'::jsonb),
  ('salate', 'Salata cu ton', 'Mix salată, ton, roșii cherry coapte, măsline, ou de prepeliță, sos sesame, semințe de susan.', 190, '270 g', '/dish-photos/salata-ton.jpg', false, 10, '{"ru": {"name": "Салат с тунцом", "description": "Микс салата, тунец, запечённые томаты черри, маслины, перепелиное яйцо, кунжутный соус, кунжут."}, "en": {"name": "Tuna Salad", "description": "Salad mix, tuna, roasted cherry tomatoes, olives, quail egg, sesame dressing, sesame seeds."}}'::jsonb),
  ('salate', 'Salata cu somon', 'Mix de salată, somon s/s, castravete, avocado, roșii cherry coapte, sos de susan, semințe de susan.', 160, '280 g', '/dish-photos/salata-somon.jpg', false, 20, '{"ru": {"name": "Салат с лососем", "description": "Микс салата, слабосолёный лосось, огурец, авокадо, запечённые томаты черри, кунжутный соус, кунжут."}, "en": {"name": "Salmon Salad", "description": "Salad mix, cured salmon, cucumber, avocado, roasted cherry tomatoes, sesame dressing, sesame seeds."}}'::jsonb),
  ('salate', 'Salata cu calmar și mango', 'Mix de salată, tentacule de calmar, mango, avocado, dressing de portocală.', 170, '280 g', '/dish-photos/salata-calmar-mango.jpg', false, 30, '{"ru": {"name": "Салат с кальмаром и манго", "description": "Микс салата, щупальца кальмара, манго, авокадо, апельсиновая заправка."}, "en": {"name": "Calamari & Mango Salad", "description": "Salad mix, calamari tentacles, mango, avocado, orange dressing."}}'::jsonb),
  ('salate', 'Salata cu vită fragedă și vinete', 'Mix de salată, carne de vită fragedă, ciuperci, ardei copți, vinete, sos de miere și muștar, semințe de susan.', 150, '400 g', '/dish-photos/salata-vita-fragede-vinete.jpg', false, 40, '{"ru": {"name": "Салат с нежной говядиной и баклажаном", "description": "Микс салата, нежная говядина, грибы, печёный перец, баклажан, медово-горчичный соус, кунжут."}, "en": {"name": "Tender Beef & Eggplant Salad", "description": "Salad mix, tender beef, mushrooms, roasted pepper, eggplant, honey-mustard sauce, sesame seeds."}}'::jsonb),
  ('salate', 'Salata Caesar cu creveți', 'Mix de salată Iceberg, sos Caesar, creveți, usturoi, roșii cherry, crutoane, cașcaval Parmigiano.', 150, '450 g', '/dish-photos/salata-caesar-creveti.jpg', false, 50, '{"ru": {"name": "Салат Цезарь с креветками", "description": "Салат Айсберг, соус Цезарь, креветки, чеснок, томаты черри, крутоны, пармиджано."}, "en": {"name": "Caesar Salad with Shrimp", "description": "Iceberg lettuce, Caesar dressing, shrimp, garlic, cherry tomatoes, croutons, Parmigiano."}}'::jsonb),
  ('salate', 'Salata Caesar cu pui', 'Mix de salată Iceberg, file de pui pane, roșii cherry, crutoane, sos Caesar, ou de prepeliță, cașcaval Parmigiano.', 140, '340 g', '/dish-photos/salata-caesar-pui.jpg', false, 60, '{"ru": {"name": "Салат Цезарь с курицей", "description": "Салат Айсберг, куриное филе в панировке, томаты черри, крутоны, соус Цезарь, перепелиное яйцо, пармиджано."}, "en": {"name": "Caesar Salad with Chicken", "description": "Iceberg lettuce, breaded chicken fillet, cherry tomatoes, croutons, Caesar dressing, quail egg, Parmigiano."}}'::jsonb),
  ('salate', 'Salata Greek Garden', 'Mix de salată, roșii cherry, ardei, castraveți, ceapă roșie, măsline, brânză bulgărească, dressing.', 110, '320 g', '/dish-photos/salata-greek-garden.jpg', false, 70, '{"ru": {"name": "Салат Грик Гарден", "description": "Микс салата, томаты черри, перец, огурцы, красный лук, маслины, болгарская брынза, заправка."}, "en": {"name": "Greek Garden Salad", "description": "Salad mix, cherry tomatoes, bell pepper, cucumber, red onion, olives, Bulgarian cheese, dressing."}}'::jsonb),
  ('supe', 'Borș roșu', 'Costiță de porc, legume, slănină condimentată, usturoi, smântână, ardei iute, pâine neagră.', 95, '680 g', '/dish-photos/bors-rosu.jpg', false, 0, '{"ru": {"name": "Борщ красный", "description": "Свиные рёбрышки, овощи, приправленное сало, чеснок, сметана, острый перец, чёрный хлеб."}, "en": {"name": "Red Borscht", "description": "Pork ribs, vegetables, seasoned lard, garlic, sour cream, hot pepper, black bread."}}'::jsonb),
  ('supe', 'Zeamă', 'Carne de pui, morcov, ardei gras, roșii, tăiței de casă, verdeață, smântână, ardei iute.', 75, '460 g', '/dish-photos/zeama.jpg', false, 10, '{"ru": {"name": "Дзама (куриный суп)", "description": "Курица, морковь, болгарский перец, томаты, домашняя лапша, зелень, сметана, острый перец."}, "en": {"name": "Zeamă (Chicken Soup)", "description": "Chicken, carrot, bell pepper, tomato, homemade noodles, herbs, sour cream, hot pepper."}}'::jsonb),
