  ('paste', 'Paste cu beef', 'Paste, mușchiuleț de vită, roșii cherry, pulpă de roșii, busuioc, usturoi, cașcaval Parmigiano.', 170, '400 g', '/dish-photos/paste-cu-beef.jpg', false, 20, '{"ru": {"name": "Паста с говядиной", "description": "Паста, вырезка говядины, томаты черри, томатная мякоть, базилик, чеснок, пармиджано."}, "en": {"name": "Beef Pasta", "description": "Pasta, beef tenderloin, cherry tomatoes, tomato pulp, basil, garlic, Parmigiano."}}'::jsonb),
  ('peste', 'Dorado cu legume baby', 'File de dorado, legume baby, boabe edamame, unt, sos de capere.', 290, '370 g', '/dish-photos/dorado-legume-baby.jpg', false, 0, '{"ru": {"name": "Дорадо с молодыми овощами", "description": "Филе дорадо, молодые овощи, эдамаме, сливочное масло, соус из каперсов."}, "en": {"name": "Dorado with Baby Vegetables", "description": "Dorado fillet, baby vegetables, edamame beans, butter, caper sauce."}}'::jsonb),
  ('peste', 'Somon cu sparanghel', 'Somon, sparanghel, zucchini, sos Parmigiano.', 320, '350 g', '/dish-photos/somon-sparanghel.jpg', false, 10, '{"ru": {"name": "Лосось со спаржей", "description": "Лосось, спаржа, цукини, соус пармиджано."}, "en": {"name": "Salmon with Asparagus", "description": "Salmon, asparagus, zucchini, Parmigiano sauce."}}'::jsonb),
  ('peste', 'Fructe de mare', 'Tentacule de calmar, creveți, midii de Marea Neagră, midii cu carne, roșii cherry, usturoi, unt, cimbru, vin alb, ciabatta.', 300, '360 g', '/dish-photos/fructe-de-mare.jpg', true, 20, '{"ru": {"name": "Морепродукты", "description": "Щупальца кальмара, креветки, черноморские мидии, мидии с мясом, томаты черри, чеснок, сливочное масло, тимьян, белое вино, чиабатта."}, "en": {"name": "Seafood Platter", "description": "Calamari tentacles, shrimp, Black Sea mussels, mussel meat, cherry tomatoes, garlic, butter, thyme, white wine, ciabatta."}}'::jsonb),
  ('carne', 'File mignon cu sparanghel', 'Mușchiuleț de vită, sparanghel, cartof baby, usturoi, unt, cimbru, sos demi-glace.', 350, '450 g', '/dish-photos/file-mignon-sparanghel.jpg', true, 0, '{"ru": {"name": "Филе миньон со спаржей", "description": "Вырезка говядины, спаржа, молодой картофель, чеснок, сливочное масло, тимьян, соус демигласс."}, "en": {"name": "Filet Mignon with Asparagus", "description": "Beef tenderloin, asparagus, baby potatoes, garlic, butter, thyme, demi-glace sauce."}}'::jsonb),
  ('carne', 'Steak New York', 'Cartof baby, usturoi, unt, cimbru, sos demi-glace.', 450, '500 g', '/dish-photos/steak-new-york.jpg', false, 10, '{"ru": {"name": "Стейк Нью-Йорк", "description": "Молодой картофель, чеснок, сливочное масло, тимьян, соус демигласс."}, "en": {"name": "New York Steak", "description": "Baby potatoes, garlic, butter, thyme, demi-glace sauce."}}'::jsonb),
  ('carne', 'Steak Cowboy', 'Cartof baby, usturoi, unt, cimbru, sos demi-glace.', 750, '850 g', '/dish-photos/steak-cowboy.jpg', true, 20, '{"ru": {"name": "Стейк Ковбой", "description": "Молодой картофель, чеснок, сливочное масло, тимьян, соус демигласс."}, "en": {"name": "Cowboy Steak", "description": "Baby potatoes, garlic, butter, thyme, demi-glace sauce."}}'::jsonb),
  ('carne', 'Medalion de porc cu cartof baby', 'Mușchiuleț de porc, cartof baby, ciuperci, usturoi, unt, cimbru, sos demi-glace.', 250, '470 g', '/dish-photos/medalion-porc-cartof-baby.jpg', false, 30, '{"ru": {"name": "Медальоны из свинины с молодым картофелем", "description": "Свиная вырезка, молодой картофель, грибы, чеснок, сливочное масло, тимьян, соус демигласс."}, "en": {"name": "Pork Medallions with Baby Potatoes", "description": "Pork tenderloin, baby potatoes, mushrooms, garlic, butter, thyme, demi-glace sauce."}}'::jsonb),
  ('carne', 'Miel cu legume', 'Carne de miel cu os, legume baby, sos demi-glace, roșii cherry, usturoi, unt, cimbru.', 370, '500 g', '/dish-photos/miel-cu-legume.jpg', false, 40, '{"ru": {"name": "Ягнёнок с овощами", "description": "Мясо ягнёнка на кости, молодые овощи, соус демигласс, томаты черри, чеснок, сливочное масло, тимьян."}, "en": {"name": "Lamb with Vegetables", "description": "Bone-in lamb, baby vegetables, demi-glace sauce, cherry tomatoes, garlic, butter, thyme."}}'::jsonb),
  ('carne', 'Steak de pui cu legume', 'Piept de pui, legume baby, unt, sos Dor Blue.', 170, '400 g', '/dish-photos/steak-pui-cu-legume.jpg', false, 50, '{"ru": {"name": "Куриный стейк с овощами", "description": "Куриная грудка, молодые овощи, сливочное масло, соус Дор Блю."}, "en": {"name": "Chicken Steak with Vegetables", "description": "Chicken breast, baby vegetables, butter, Dor Blue cheese sauce."}}'::jsonb),
  ('carne', 'File de rață cu piure de cartof', 'File de rață, piure de cartof, sos de vișine.', 280, '500 g', '/dish-photos/file-rata-pireu-batat.jpg', false, 60, '{"ru": {"name": "Филе утки с картофельным пюре", "description": "Филе утки, картофельное пюре, вишнёвый соус."}, "en": {"name": "Duck Fillet with Mashed Potatoes", "description": "Duck fillet, mashed potatoes, cherry sauce."}}'::jsonb),
  ('burgeri', 'Burger American cu carne maturată și sos BBQ', 'Chiflă crocantă, carne maturată, roșii, cașcaval, castraveți murați, ceapă roșie, cartofi prăjiți, sos BBQ, ketchup.', 170, '470 g', null, false, 0, '{"ru": {"name": "Бургер Американ с выдержанной говядиной и соусом BBQ", "description": "Хрустящая булочка, выдержанная говядина, томаты, сыр, маринованные огурцы, красный лук, картофель фри, соус BBQ, кетчуп."}, "en": {"name": "American Burger with Aged Beef & BBQ Sauce", "description": "Crispy bun, aged beef patty, tomato, cheese, pickles, red onion, fries, BBQ sauce, ketchup."}}'::jsonb),
  ('burgeri', 'Burger Krispy cu file de pui', 'Chiflă crocantă, salată verde, piept de pui pane, Cheddar, roșii, cartofi prăjiți, ketchup.', 150, '370 g', null, false, 10, '{"ru": {"name": "Бургер Криспи с куриным филе", "description": "Хрустящая булочка, листья салата, куриное филе в панировке, чеддер, томаты, картофель фри, кетчуп."}, "en": {"name": "Krispy Chicken Burger", "description": "Crispy bun, lettuce, breaded chicken fillet, Cheddar, tomato, fries, ketchup."}}'::jsonb),
