  ('platouri', 'Platou Grand Steakhouse', 'Steak Cowboy, steak New York, steak Chateaubriand, cartofi copți, roșii cherry, legume grill, sos de trufe, sos demi-glace.', 1500, '2000 g', '/dish-photos/platou-grand-steakhouse.jpg', true, 0, '{"ru": {"name": "Платтер Гранд Стейкхаус", "description": "Стейк Ковбой, стейк Нью-Йорк, стейк Шатобриан, печёный картофель, томаты черри, овощи гриль, трюфельный соус, соус демигласс."}, "en": {"name": "Grand Steakhouse Platter", "description": "Cowboy steak, New York steak, Chateaubriand steak, baked potatoes, cherry tomatoes, grilled vegetables, truffle sauce, demi-glace sauce."}}'::jsonb),
