  ('garnituri', 'Baghetă cu unt și usturoi', 'Baghetă crocantă, unt aromat cu usturoi.', 40, null, null, false, 10, '{"ru": {"name": "Багет с чесночным маслом", "description": "Хрустящий багет, ароматное масло с чесноком."}, "en": {"name": "Garlic Butter Baguette", "description": "Crispy baguette with fragrant garlic butter."}}'::jsonb),
