  ('garnituri', 'Legume grill', 'Selecție de legume la grătar.', 85, '350 g', '/dish-photos/legume-grill.jpg', false, 30, '{"ru": {"name": "Овощи гриль", "description": "Ассорти овощей на гриле."}, "en": {"name": "Grilled Vegetables", "description": "A selection of grilled vegetables."}}'::jsonb),
  ('garnituri', 'Sparanghel', 'Sparanghel proaspăt.', 120, '100 g', '/dish-photos/sparanghel.jpg', false, 40, '{"ru": {"name": "Спаржа", "description": "Свежая спаржа."}, "en": {"name": "Asparagus", "description": "Fresh asparagus."}}'::jsonb),
