  ('deserturi', 'Tiramisu', 'Clasicul desert italian cu mascarpone și cafea.', 95, null, '/dish-photos/tiramisu.jpg', false, 30, '{"ru": {"name": "Тирамису", "description": "Классический итальянский десерт с маскарпоне и кофе."}, "en": {"name": "Tiramisu", "description": "The classic Italian dessert with mascarpone and coffee."}}'::jsonb),
  ('deserturi', 'Mango', 'Variantă de desert cu mango.', 110, null, '/dish-photos/mango-desert.jpg', false, 40, '{"ru": {"name": "Манго", "description": "Десерт с манго."}, "en": {"name": "Mango", "description": "A mango-based dessert."}}'::jsonb),
  ('deserturi', 'Boabă de cafea', 'Variantă de desert cu aromă de cafea.', 110, null, '/dish-photos/boaba-de-cafea.jpg', false, 50, '{"ru": {"name": "Кофейное зерно", "description": "Десерт с кофейным ароматом."}, "en": {"name": "Coffee Bean", "description": "A coffee-flavored dessert."}}'::jsonb),
  ('deserturi', 'Zmeură', 'Variantă de desert cu zmeură.', 110, null, '/dish-photos/zmeura.jpg', false, 60, '{"ru": {"name": "Малина", "description": "Десерт с малиной."}, "en": {"name": "Raspberry", "description": "A raspberry-based dessert."}}'::jsonb)
